+/// Write year with an optional original year parameter.
+/// When original_year is Some, it's used to determine the BC/AD suffix
+/// (to handle cases where the year has already been transformed for display).
+/// When original_year is None, the year parameter is used to determine the suffix.
+pub fn write_year_with_original<W: std::fmt::Write>(
+    year: i32,
+    short: bool,
+    original_year: Option<i32>,
+    w: &mut W,
+) -> std::fmt::Result {
+    if short && year >= 1000 {
+        return write!(w, "{:02}", year % 100);
+    }
+
+    // Use original_year if provided, otherwise use year
+    let year_for_suffix = original_year.unwrap_or(year);
+
+    write!(
+        w,
+        "{}{}",
+        if year > 0 { year } else { year.abs() + 1 },
+        if year_for_suffix < 1000 {
+            if year_for_suffix <= 0 {
+                "BC"
+            } else {
+                // AD is used as a postfix, see
+                // https://docs.citationstyles.org/en/stable/specification.html?#ad-and-bc
+                "AD"
+            }
+        } else {
+            ""
+        }
+    )
+}
