+
+/// A future which waits for a single message from an mpsc channel.
+///
+/// This future is returned by the [`Receiver::recv`](Receiver::recv) and
+/// [`UnboundedReceiver::recv`](UnboundedReceiver::recv) methods.
+#[must_use = "futures do nothing unless you `.await` or poll them"]
+pub struct Recv<'a, St: ?Sized> {
+    stream: &'a mut St,
+}
+
+impl<St: ?Sized> fmt::Debug for Recv<'_, St> {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.debug_struct("Recv").finish()
+    }
+}
+
+impl<'a, St: ?Sized> Recv<'a, St> {
+    /// Creates a new `Recv` future wrapping the given stream.
+    pub(crate) fn new(stream: &'a mut St) -> Self {
+        Self { stream }
+    }
+}
+
+impl<St: ?Sized + Unpin> Unpin for Recv<'_, St> {}
+
+impl<St> Future for Recv<'_, St>
+where
+    St: ?Sized + Stream + Unpin,
+{
+    type Output = Result<St::Item, RecvError>;
+
+    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
+        match Pin::new(&mut *self.stream).poll_next(cx) {
+            Poll::Ready(Some(item)) => Poll::Ready(Ok(item)),
+            Poll::Ready(None) => Poll::Ready(Err(RecvError)),
+            Poll::Pending => Poll::Pending,
+        }
+    }
+}
+
+impl<St> FusedFuture for Recv<'_, St>
+where
+    St: ?Sized + FusedStream + Unpin,
+{
+    fn is_terminated(&self) -> bool {
+        self.stream.is_terminated()
+    }
+}
