+++ b/rlp/src/impls.rs
@@ -48,7 +48,11 @@ impl<T: Decodable> Decodable for Box<T> {

 impl Encodable for bool {
 	fn rlp_append(&self, s: &mut RlpStream) {
-		s.encoder().encode_iter(once(if *self { 1u8 } else { 0 }));
+		if *self {
+			s.encoder().encode_iter(once(1u8));
+		} else {
+			s.encoder().encode_iter(empty());
+		}
 	}
 }

@@ -56,7 +60,11 @@ impl Decodable for bool {
 	fn decode(rlp: &Rlp) -> Result<Self, DecoderError> {
 		rlp.decoder().decode_value(|bytes| match bytes.len() {
 			0 => Ok(false),
-			1 => Ok(bytes[0] != 0),
+			1 => match bytes[0] {
+				0 => Err(DecoderError::Custom("invalid boolean value")),
+				1 => Ok(true),
+				_ => Err(DecoderError::Custom("invalid boolean value")),
+			},
 			_ => Err(DecoderError::RlpIsTooBig),
 		})
 	}

