diff --git a/src/generation/generate.rs b/src/generation/generate.rs
index 27e99e3..84459d2 100644
--- a/src/generation/generate.rs
+++ b/src/generation/generate.rs
@@ -1695,14 +1695,30 @@ fn gen_arrow_func_expr<'a>(node: &'a ArrowExpr, context: &mut Context<'a>) -> Pr
   }

   fn get_should_use_parens<'a>(node: &ArrowSignature<'a>, context: &Context<'a>) -> bool {
-    let requires_parens = node.params().len() != 1 || node.return_type().is_some() || is_first_param_not_identifier_or_has_type_annotation(node.params());
+    let has_single_param = node.params().len() == 1;
+    let requires_parens = !has_single_param || node.return_type().is_some() || is_first_param_not_identifier_or_has_type_annotation(node.params());

     return if requires_parens {
       true
     } else {
       match context.config.arrow_function_use_parentheses {
         UseParentheses::Force => true,
-        UseParentheses::PreferNone => false,
+        UseParentheses::PreferNone => {
+          // Check if we should preserve parens due to a leading block comment on the parameter
+          // If there are parens and there's a leading block comment on the same line,
+          // we need to keep the parens to preserve the comment's association with the parameter
+          if has_parens(node, context) {
+            let first_param = node.params().first().unwrap();
+            if let Pat::Ident(pat_ident) = first_param {
+              let mut leading_comments = pat_ident.leading_comments_fast(context.program);
+              let param_start_line = pat_ident.start_line_fast(context.program);
+              if leading_comments.any(|c| c.kind == CommentKind::Block && c.start_line_fast(context.program) == param_start_line) {
+                return true;
+              }
+            }
+          }
+          false
+        }
         UseParentheses::Maintain => has_parens(node, context),
       }
     };

