+/// Detects whether a call matches the pattern `fn1(fn2())` or similar subsetting
+/// forms that should be formatted in a hugging style, i.e., without expanding
+/// the inner call onto a new line when possible.
+///
+/// Returns `Ok(true)` if the call is eligible for "hugging" (exactly one argument,
+/// that argument is a call/subset expression, and neither the argument nor the
+/// closing token have attached comments); `Ok(false)` otherwise. Propagates any
+/// syntax errors.
+fn is_hugging_call(items: &[FormatCallArgument], r_token: SyntaxResult<RSyntaxToken>) -> SyntaxResult<bool> {
+    // Hugging only applies when there's exactly one argument
+    if items.len() != 1 {
+        return Ok(false);
+    }
+
+    let item = &items[0];
+
+    // Check if the argument has comments - if so, don't hug
+    let element = item.element();
+    let argument = element.node()?;
+
+    // Check for comments on the argument itself
+    if argument.syntax().has_comments_direct() {
+        return Ok(false);
+    }
+
+    // Check if the argument is a call or subset expression
+    if let Some(value) = argument.value() {
+        match value {
+            // Call expression: fn1(fn2())
+            AnyRExpression::RCall(_) => {}
+            // Subset expression: fn1(x$y)
+            AnyRExpression::RSubset(_) => {}
+            // Subset2 expression: fn1(x[[i]])
+            AnyRExpression::RSubset2(_) => {}
+            // Other expressions are not eligible for hugging
+            _ => return Ok(false),
+        }
+    } else {
+        // Not a value argument (shouldn't happen for normal calls)
+        return Ok(false);
+    }
+
+    // Check if the closing token has leading or trailing comments - if so, don't hug
+    let r_token = r_token?;
+    if r_token.has_leading_comments() || r_token.has_trailing_comments() {
+        return Ok(false);
+    }
+
+    Ok(true)
+}
+
+/// Formats a function/subsetting call in "hugging" style.
+/// This keeps `fn1(fn2())` on a single line when possible.
+fn write_hugging_arguments(
+    l_token: RSyntaxToken,
+    leading_holes: Vec<FormatCallArgumentHole>,
+    arguments: Vec<FormatCallArgument>,
+    r_token: RSyntaxToken,
+    f: &mut RFormatter,
+) -> FormatResult<()> {
+    // Try to write the hugging variant (all on one line)
+    let snapshot = f.state_snapshot();
+    
+    let result = write!(
+        f,
+        [
+            l_token.format(),
+            format_with(|f| { f.join().entries(leading_holes.iter()).finish() }),
+            maybe_space(!leading_holes.is_empty() && !arguments.is_empty()),
+            format_with(|f| {
+                f.join_with(space())
+                    .entries(arguments.iter())
+                    .finish()
+            }),
+            r_token.format()
+        ]
+    );
+
+    // If the hugging variant doesn't fit, fall back to expanded
+    if matches!(result, Err(FormatError::PoorLayout)) {
+        f.restore_state_snapshot(snapshot);
+        write!(
+            f,
+            [FormatAllArgsBrokenOut {
+                l_token: &l_token.format(),
+                leading_holes: &leading_holes,
+                args: &arguments,
+                r_token: &r_token.format(),
+                expand: true,
+            }]
+        )
+    } else {
+        result
+    }
+}
+
