issue_context:
Consider implementing DoubleEndedIterator for Chain
We may sometimes want errors that are printed inside-out from lowest level to highest.

```rust
for e in error.chain().rev() {
    println!("{}", e);
}
```

This may requires some buffering but that's fine, the caller would be doing it anyway in this situation.

patch:
diff --git a/src/error.rs b/src/error.rs
index f51033e..f1251bf 100644
--- a/src/error.rs
+++ b/src/error.rs
@@ -674,6 +674,9 @@ impl ErrorImpl<()> {
     pub(crate) fn chain(&self) -> Chain {
         Chain {
             next: Some(self.error()),
+            v: Vec::new(),
+            front_consumed: 0,
+            back_consumed: 0,
         }
     }
 }
@@ -731,8 +734,64 @@ impl<'a> Iterator for Chain<'a> {
     type Item = &'a (dyn StdError + 'static);

     fn next(&mut self) -> Option<Self::Item> {
+        // If we've collected all elements, iterate from the vector
+        if self.next.is_none() {
+            let total_consumed = self.front_consumed + self.back_consumed;
+            if self.front_consumed < self.v.len() - self.back_consumed {
+                let item = self.v[self.front_consumed];
+                self.front_consumed += 1;
+                return Some(item);
+            }
+            return None;
+        }
+        
+        // Otherwise, continue forward iteration through the chain
         let next = self.next?;
+        self.v.push(next);
         self.next = next.source();
+        self.front_consumed += 1;
         Some(next)
     }
+
+    fn size_hint(&self) -> (usize, Option<usize>) {
+        let len = self.len();
+        (len, Some(len))
+    }
+}
+
+impl<'a> DoubleEndedIterator for Chain<'a> {
+    fn next_back(&mut self) -> Option<Self::Item> {
+        // Collect all remaining elements if not already done
+        if self.next.is_some() {
+            while let Some(error) = self.next.take() {
+                self.v.push(error);
+                self.next = error.source();
+            }
+        }
+        
+        // Return elements from the back of the vector
+        let total_consumed = self.front_consumed + self.back_consumed;
+        if total_consumed < self.v.len() {
+            self.back_consumed += 1;
+            Some(self.v[self.v.len() - self.back_consumed])
+        } else {
+            None
+        }
+    }
+}
+
+impl<'a> ExactSizeIterator for Chain<'a> {
+    fn len(&self) -> usize {
+        // Count buffered elements that haven't been consumed yet
+        let buffered_remaining = self.v.len().saturating_sub(self.front_consumed + self.back_consumed);
+        
+        // Count unbuffered elements still in the chain
+        let mut count = buffered_remaining;
+        let mut current = self.next;
+        while let Some(error) = current {
+            count += 1;
+            current = error.source();
+        }
+        count
+    }
 }
