+// Verification that all public API types have consistent serialize()/deserialize() methods
+use opaque_ke::ciphersuite::CipherSuite;
+use opaque_ke::{ClientLogin, ClientRegistration, RegistrationRequest};
+use rand::{rngs::OsRng, RngCore};
+use sha2::Sha512;
+use curve25519_dalek::ristretto::RistrettoPoint;
+
+struct Default;
+impl CipherSuite for Default {
+    type Group = RistrettoPoint;
+    type KeyExchange = opaque_ke::key_exchange::tripledh::TripleDH;
+    type Hash = Sha512;
+    type SlowHash = opaque_ke::slow_hash::NoOpHash;
+}
+
+fn main() -> Result<(), Box<dyn std::error::Error>> {
+    println!("Verifying serialization API consistency...\n");
+    
+    let mut rng = OsRng;
+    
+    // Test 1: RegistrationRequest
+    println!("✓ RegistrationRequest:");
+    let client_reg_start = ClientRegistration::<Default>::start(&mut rng, b"password")?;
+    let reg_req = client_reg_start.message;
+    let bytes = reg_req.serialize();
+    let _reg_req2 = RegistrationRequest::<Default>::deserialize(&bytes)?;
+    assert_eq!(bytes.len(), 32); // RistrettoPoint is 32 bytes
+    println!("  - serialize() produces {} bytes", bytes.len());
+    println!("  - deserialize() successfully reconstructs object");
+    
+    // Test 2: ClientRegistration
+    println!("\n✓ ClientRegistration:");
+    let client_reg = ClientRegistration::<Default>::start(&mut rng, b"password")?.state;
+    let bytes = client_reg.serialize();
+    let _client_reg2 = ClientRegistration::<Default>::deserialize(&bytes)?;
+    println!("  - serialize() produces {} bytes", bytes.len());
+    println!("  - deserialize() successfully reconstructs object");
+    
+    // Test 3: ClientLogin
+    println!("\n✓ ClientLogin:");
+    let client_login = ClientLogin::<Default>::start(
+        &mut rng, 
+        b"password", 
+        opaque_ke::ClientLoginStartParameters::default()
+    )?.state;
+    let bytes = client_login.serialize();
+    let _client_login2 = ClientLogin::<Default>::deserialize(&bytes)?;
+    println!("  - serialize() produces {} bytes", bytes.len());
+    println!("  - deserialize() successfully reconstructs object");
+    
+    // Verify backward compatibility
+    println!("\n✓ Backward Compatibility:");
+    #[allow(deprecated)]
+    {
+        let client_reg_for_test = ClientRegistration::<Default>::start(&mut rng, b"password")?.state;
+        let bytes_new = client_reg_for_test.serialize();
+        let bytes_old = client_reg_for_test.to_bytes();
+        assert_eq!(bytes_new, bytes_old);
+        println!("  - to_bytes() still works and produces identical output to serialize()");
+    }
+    
+    println!("\n✅ All verification tests passed!");
+    println!("✅ Public API now consistently uses serialize()/deserialize() naming convention");
+    Ok(())
+}
