+    fn strict_encode<E: ::std::io::Write>(
+        &self,
+        mut e: E,
+    ) -> Result<usize, strict_encoding::Error> {
+        let mut len = self.id.strict_encode(&mut e)?;
+        len += self.lifetime.strict_encode(&mut e)?;
+        len += self.addendum.strict_encode(&mut e)?;
+        // Encode from_height as Option<u64>
+        match self.from_height {
+            Some(height) => {
+                len += 1u8.strict_encode(&mut e)?;
+                len += height.strict_encode(&mut e)?;
+            }
+            None => {
+                len += 0u8.strict_encode(&mut e)?;
+            }
+        }
+        Ok(len)
+    }
+}
