issue_context:
Accept `.var` shorthand inside of parens
For example:

```rust
#[derive(Error, Debug)]
pub enum Error {
    #[error("{}", print(.0))]
    Io(io::Error),
}

fn print(error: &io::Error) -> String {
    unimplemented!()
}
```

We should expand `.var` immediately after `(`, not just `,`.

patch:
diff --git a/impl/src/attr.rs b/impl/src/attr.rs
index b23c15b..712c2b0 100644
--- a/impl/src/attr.rs
+++ b/impl/src/attr.rs
@@ -4,6 +4,67 @@ use std::iter::once;
 use syn::parse::{Nothing, Parse, ParseStream};
 use syn::{Attribute, Error, Field, Ident, Index, LitInt, LitStr, Result, Token};

+// Transform .var shorthand inside a token stream
+fn transform_var_shorthand(stream: TokenStream) -> TokenStream {
+    let mut result = TokenStream::new();
+    let tokens: Vec<TokenTree> = stream.into_iter().collect();
+    let mut i = 0;
+    let mut last_is_comma = false;
+    
+    while i < tokens.len() {
+        let token = &tokens[i];
+        
+        // Check for .var shorthand after comma or at the very start (i == 0)
+        if (last_is_comma || i == 0) && matches!(token, TokenTree::Punct(p) if p.as_char() == '.') {
+            if i + 1 < tokens.len() {
+                match &tokens[i + 1] {
+                    TokenTree::Ident(ident) => {
+                        // Skip the dot and add just the identifier
+                        result.extend(once(TokenTree::Ident(ident.clone())));
+                        i += 2; // skip dot and identifier
+                        last_is_comma = false;
+                        continue;
+                    }
+                    TokenTree::Literal(lit) => {
+                        // Check if it's an integer literal
+                        let lit_str = lit.to_string();
+                        if lit_str.chars().all(|c| c.is_ascii_digit()) {
+                            if let Ok(index) = lit_str.parse::<usize>() {
+                                // Skip the dot and add _index
+                                let ident = format_ident!("_{}", index, span = lit.span());
+                                result.extend(once(TokenTree::Ident(ident)));
+                                i += 2; // skip dot and literal
+                                last_is_comma = false;
+                                continue;
+                            }
+                        }
+                    }
+                    _ => {}
+                }
+            }
+        }
+        
+        // Handle nested groups recursively
+        if let TokenTree::Group(group) = token {
+            if group.delimiter() == proc_macro2::Delimiter::Parenthesis {
+                let transformed = transform_var_shorthand(group.stream());
+                let new_group = proc_macro2::Group::new(group.delimiter(), transformed);
+                result.extend(once(TokenTree::Group(new_group)));
+                i += 1;
+                last_is_comma = false;
+                continue;
+            }
+        }
+        
+        // Regular token
+        last_is_comma = matches!(token, TokenTree::Punct(p) if p.as_char() == ',');
+        result.extend(once(token.clone()));
+        i += 1;
+    }
+    
+    result
+}
