+    // Test negative zero
+    test_literal("-0", Literal::i32_suffixed(0i32));
+    
+    // Test very large negative numbers
+    test_literal("-9223372036854775808 (i64::MIN)", Literal::i64_suffixed(-9223372036854775808i64));
+    
+    // Test negative hex
+    test_literal("-0xFF", Literal::i32_suffixed(-255i32));
+    
+    // Test negative octal
+    test_literal("-0o777", Literal::i32_suffixed(-511i32));
+    
+    // Test negative binary
+    test_literal("-0b1111", Literal::i32_suffixed(-15i32));
+    
+    // Test negative with exponent notation (should NOT be split)
+    test_literal("-1e10 (float with exponent)", Literal::f64_suffixed(-1e10f64));
+    
+    // Test negative float with decimal point (should NOT be split)
+    test_literal("-3.14", Literal::f64_suffixed(-3.14f64));
+    
+    // Test positive literals (should NOT be split)
+    test_literal("+42 (positive)", Literal::i32_suffixed(42i32));
+    
+    // Test using From<TokenTree> directly
+    println!("\n=== Testing From<TokenTree> for TokenStream ===\n");
+    let lit = Literal::i32_suffixed(-42i32);
+    let stream: TokenStream = TokenTree::Literal(lit).into();
+    let tokens: Vec<_> = stream.into_iter().collect();
+    println!("From<TokenTree>: {} token(s)", tokens.len());
+    for (i, tt) in tokens.iter().enumerate() {
+        match tt {
+            TokenTree::Literal(l) => println!("  [{}] Literal: {}", i, l),
+            TokenTree::Punct(p) => println!("  [{}] Punct: '{}'", i, p.as_char()),
+            _ => println!("  [{}] {:?}", i, tt),
+        }
+    }
+}
+
+fn test_literal(name: &str, lit: Literal) {
+    let mut tokens = TokenStream::new();
+    tokens.extend(std::iter::once(TokenTree::Literal(lit)));
+    
+    let token_vec: Vec<_> = tokens.into_iter().collect();
+    print!("{:40}: {} token(s) - ", name, token_vec.len());
+    
+    for (i, tt) in token_vec.iter().enumerate() {
+        if i > 0 {
+            print!(" + ");
+        }
+        match tt {
+            TokenTree::Literal(l) => print!("{}", l),
+            TokenTree::Punct(p) => print!("'{}'", p.as_char()),
+            _ => print!("{:?}", tt),
+        }
+    }
+    println!();
+}
diff --git a/examples/test_issue_scenario.rs b/examples/test_issue_scenario.rs
new file mode 100644
