--- /dev/null
+++ b/examples/test_issue_scenario.rs
@@ -0,0 +1,54 @@
+/// This test reproduces the exact scenario from the issue description.
+/// 
+/// Before the fix:
+/// - Without fallback::force(): 2 tokens (rustc's behavior)
+/// - With fallback::force(): 1 token (incorrect fallback behavior)
+/// 
+/// After the fix:
+/// - Both should show 2 tokens (matching rustc's behavior)
+
+use std::iter;
+use proc_macro2::{TokenStream, TokenTree, Literal};
+
+fn main() {
+    println!("=== Testing Issue Scenario ===\n");
+    
+    // Test without forcing fallback
+    println!("Without forcing fallback:");
+    test_negative_literal();
+    
+    // Force fallback and test again
+    println!("\nWith fallback forced:");
+    proc_macro2::fallback::force();
+    test_negative_literal();
+}
+
+fn test_negative_literal() {
+    let int: i32 = -3;
+    let mut tokens = TokenStream::new();
+    tokens.extend(iter::once(TokenTree::Literal(Literal::i32_suffixed(int))));
+    
+    let token_vec: Vec<_> = tokens.into_iter().collect();
+    println!("  Number of tokens: {}", token_vec.len());
+    
+    for (i, tt) in token_vec.iter().enumerate() {
+        match tt {
+            TokenTree::Literal(lit) => println!("    [{}] Literal: {}", i, lit),
+            TokenTree::Punct(punct) => println!("    [{}] Punct: '{}' (spacing: {:?})", i, punct.as_char(), punct.spacing()),
+            _ => println!("    [{}] {:?}", i, tt),
+        }
+    }
+    
+    // Verify the expected behavior
+    assert_eq!(token_vec.len(), 2, "Expected 2 tokens: '-' and '3i32'");
+    match &token_vec[0] {
+        TokenTree::Punct(p) => assert_eq!(p.as_char(), '-', "First token should be '-'"),
+        _ => panic!("First token should be a Punct '-'"),
+    }
+    match &token_vec[1] {
+        TokenTree::Literal(l) => assert_eq!(l.to_string(), "3i32", "Second token should be '3i32'"),
+        _ => panic!("Second token should be a Literal '3i32'"),
+    }
+    
+    println!("  ✓ Correctly split into two tokens!");
+}
