+    /// Extends the binary heap with a sequence of references by copying
+    /// each element and pushing it, enabling `heap.extend(&[v1, v2, …])`.
+    fn extend<I: IntoIterator<Item = &'a T>>(&mut self, iter: I) {
+        for item in iter {
+            self.push(*item);
+        }
+    }
+}
