-/// True if `path` is a usable executable (not an empty/text stub).
-///
-/// Rejects zero-byte files, HTTP/HTML placeholders, and random blobs.
-/// Accepts ELF binaries and shebang shell wrappers when executable.
-pub fn is_usable_binary(path: &str) -> bool {
-    let p = std::path::Path::new(path);
-    let Ok(meta) = std::fs::metadata(p) else {
-        return false;
-    };
-    if !meta.is_file() || meta.len() == 0 {
-        return false;
-    }
-    #[cfg(unix)]
-    {
-        use std::os::unix::fs::PermissionsExt;
-        if meta.permissions().mode() & 0o111 == 0 {
-            return false;
-        }
-    }
-    // Read only a header — full miner binaries can be multi‑MB.
-    let mut file = match std::fs::File::open(p) {
-        Ok(f) => f,
-        Err(_) => return false,
-    };
-    let mut head = [0u8; 512];
-    let n = match std::io::Read::read(&mut file, &mut head) {
-        Ok(n) => n,
-        Err(_) => return false,
-    };
-    let head = &head[..n];
-    if is_download_placeholder(head) {
-        return false;
-    }
-    // Require a recognized executable header so 65–1024 B HTML/error stubs
-    // with +x do not beat real binaries in detect_binary_paths order.
-    looks_like_executable_header(head)
-}
-
-fn is_download_placeholder(bytes: &[u8]) -> bool {
-    let text = String::from_utf8_lossy(bytes);
-    let trimmed = text.trim();
-    if trimmed.is_empty() {
-        return true;
-    }
-    let lower = trimmed.to_ascii_lowercase();
-    lower == "not found"
-        || lower == "404 not found"
-        || lower == "forbidden"
-        || lower == "error"
-        || lower == "bad gateway"
-        || lower == "service unavailable"
-        || lower.starts_with("<!doctype")
-        || lower.starts_with("<html")
-}
-
-fn looks_like_executable_header(bytes: &[u8]) -> bool {
-    // Shebang scripts (shell launch wrappers).
-    if bytes.starts_with(b"#!") {
-        return true;
-    }
-    // ELF: magic + class + e_type (ET_EXEC / ET_DYN). Rejects truncated
-    // downloads that only retain the 4-byte magic prefix.
-    if bytes.len() >= 18 && bytes[0..4] == [0x7f, b'E', b'L', b'F'] {
-        let class = bytes[4]; // 1 = ELFCLASS32, 2 = ELFCLASS64
-        if class != 1 && class != 2 {
-            return false;
-        }
-        // e_type at offset 16; EI_DATA (bytes[5]) selects byte order.
-        let e_type = match bytes[5] {
-            1 => u16::from_le_bytes([bytes[16], bytes[17]]), // ELFDATA2LSB
-            2 => u16::from_be_bytes([bytes[16], bytes[17]]), // ELFDATA2MSB
-            _ => return false,
-        };
-        const ET_EXEC: u16 = 2;
-        const ET_DYN: u16 = 3;
-        return e_type == ET_EXEC || e_type == ET_DYN;
-    }
-    false
-}
