+        .extract_tensor_f32(tensor_name, st_path.to_str().unwrap())
+        .unwrap();
+
+    // INT4 unpacking: 2 elements per byte
+    // 0x12 -> low=2, high=1
+    // 0x34 -> low=4, high=3
+    // 0x56 -> low=6, high=5
+    // 0x78 -> low=8, high=7
+    assert_eq!(extracted, vec![2.0, 1.0, 4.0, 3.0, 6.0, 5.0, 8.0, 7.0]);
+
+    // Cleanup
+    let _ = std::fs::remove_dir_all(&tmp_dir);
