+            t,
+            intensity,
+            decay_sum,
+            if i == 0 { " (first event)" } else { "" }
+        );
+    }
+
+    let batch = compute_hawkes(&event_times, &params);
+    println!(
+        "Final streaming intensity={:.3} (events={}); batch intensity={:.3}",
+        intensity,
+        event_times.len(),
+        batch.intensity
+    );
+    println!();
