+        _: i32,
+        _: i32,
+        _: i32,
+    ) -> GpuResult<()> {
+        Err(GpuError::NoGpu)
+    }
+    pub fn poisson_encode(
+        &self,
+        _: &GpuBuffer<f32>,
+        _: &mut GpuBuffer<u32>,
+        _: u32,
+    ) -> GpuResult<()> {
+        Err(GpuError::NoGpu)
+    }
+
+    pub fn satsolver_extract_async(
