+        let result = manager.create(&repo_root, "acme", "test-repo", "job-sym", "branch-sym");
+        assert!(
+            matches!(result, Err(Error::SandboxViolation { .. })),
+            "expected SandboxViolation, got {result:?}"
+        );
+    }
+}
